#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long d;
    cin >> d;
    vector<string> roots(d);
    for (int i = 0; i < d; i++) cin >> roots[i];
    long long m;
    cin >> m;
    vector<string> words(m);
    for (int i = 0; i < m; i++) cin >> words[i];

    vector<vector<int>> child(1, vector<int>(26, -1));
    vector<char> ends(1, 0);
    for (const string& root : roots) {
        int node = 0;
        for (char c : root) {
            int k = c - 'a';
            if (child[node][k] < 0) {
                int fresh = (int)child.size();
                child[node][k] = fresh;
                child.push_back(vector<int>(26, -1));
                ends.push_back(0);
            }
            node = child[node][k];
        }
        ends[node] = 1;
    }
    for (size_t w = 0; w < words.size(); w++) {
        const string& word = words[w];
        int node = 0;
        size_t cut = word.size();
        for (size_t i = 0; i < word.size(); i++) {
            node = child[node][word[i] - 'a'];
            if (node < 0) break;
            if (ends[node]) {
                cut = i + 1;
                break;
            }
        }
        cout << (w ? " " : "") << word.substr(0, cut);
    }
    cout << "\n";

    return 0;
}

