import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long d = Long.parseLong(next());
        String[] roots = new String[(int) d];
        for (int i = 0; i < roots.length; i++) roots[i] = next();
        long m = Long.parseLong(next());
        String[] words = new String[(int) m];
        for (int i = 0; i < words.length; i++) words[i] = next();

        List<int[]> child = new ArrayList<>();
        List<Boolean> ends = new ArrayList<>();
        child.add(new int[26]);
        Arrays.fill(child.get(0), -1);
        ends.add(false);
        for (String root : roots) {
            int node = 0;
            for (char c : root.toCharArray()) {
                int k = c - 'a';
                if (child.get(node)[k] < 0) {
                    int[] row = new int[26];
                    Arrays.fill(row, -1);
                    child.add(row);
                    ends.add(false);
                    child.get(node)[k] = child.size() - 1;
                }
                node = child.get(node)[k];
            }
            ends.set(node, true);
        }
        StringBuilder out = new StringBuilder();
        for (int w = 0; w < words.length; w++) {
            String word = words[w];
            int node = 0;
            int cut = word.length();
            for (int i = 0; i < word.length(); i++) {
                node = child.get(node)[word.charAt(i) - 'a'];
                if (node < 0) break;
                if (ends.get(node)) {
                    cut = i + 1;
                    break;
                }
            }
            out.append(w > 0 ? " " : "").append(word, 0, cut);
        }
        System.out.println(out);
    }
}
